import '../src/host_compaction.dart';

AssistantMessage _assistant(Model model, String text) => AssistantMessage(
  content: [TextContent(text: text)],
  api: model.api,
  provider: model.provider,
  model: model.id,
  usage: Usage.zero,
  stopReason: StopReason.stop,
  timestamp: DateTime.now(),
);

bool _isSummarization(Context context) =>
    context.systemPrompt == summarizationSystemPrompt;

StreamFunction textStream(String turnText, {String summary = 'summary'}) {
  return (model, context, {cancelToken}) {
    final stream = AssistantMessageEventStream();
    stream.push(
      DoneEvent(
        reason: StopReason.stop,
        message: _assistant(
          model,
          _isSummarization(context) ? summary : turnText,
        ),
      ),
    );
    stream.end();
    return stream;
  };
}

void main() {
  test('REPRO: manual compact re-fire pass count', () async {
    final fs = MemoryFileSystem();
    final repo = JsonlSessionRepo(fs: fs, sessionsRoot: '/sessions');
    final session = await repo.create(JsonlSessionCreateOptions(cwd: '/w'));
    final model = Model(
      id: 'scripted-model',
      name: 'scripted-model',
      api: 'test-api',
      provider: 'test-provider',
      baseUrl: 'https://endpoint.invalid',
      contextWindow: 512,
      maxTokens: 4096,
      input: const ['text'],
    );
    final agent = Agent(
      model: model,
      systemPrompt: '',
      streamFunction: textStream('reply'),
      toolRegistry: ToolRegistry(const []),
    );
    final logs = <String>[];
    final notices = <String>[];
    final runner = ExtensionCompactionRunner(
      session: session,
      agent: agent,
      log: logs.add,
      notice: notices.add,
    );
    Future<void> seed(String text) async {
      await session.appendMessage(UserMessage.text(text));
    }

    await seed('u1${'a' * 1200}');
    final outcome = await runner.manualCompact();
    // ignore: avoid_print
    print('outcome: ran=${outcome.ran} before=${outcome.before} '
        'after=${outcome.after} exhausted=${outcome.exhausted}');
    // ignore: avoid_print
    print('logs:');
    for (final l in logs) {
      // ignore: avoid_print
      print('  $l');
    }
    // ignore: avoid_print
    print('notices: $notices');
    expect(true, isTrue);
  });
}

